#include <string>
#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int beautySum(string s) {
        int n = s.size();
        int total_beauty = 0;
        for (int i = 0; i < n; ++i) {
            vector<int> freq(26, 0);
            for (int j = i; j < n; ++j) {
                freq[s[j] - 'a']++;
                int mx = 0, mn = 1000;
                for (int c = 0; c < 26; ++c) {
                    if (freq[c] > 0) {
                        mx = max(mx, freq[c]);
                        mn = min(mn, freq[c]);
                    }
                }
                total_beauty += (mx - mn);
            }
        }
        return total_beauty;
    }
};

class Solution {
    public int beautySum(String s) {
        int n = s.length();
        int totalBeauty = 0;
        for (int i = 0; i < n; ++i) {
            int[] freq = new int[26];
            for (int j = i; j < n; ++j) {
                freq[s.charAt(j) - 'a']++;
                int mx = 0, mn = 1000;
                for (int c = 0; c < 26; ++c) {
                    if (freq[c] > 0) {
                        if (freq[c] > mx) mx = freq[c];
                        if (freq[c] < mn) mn = freq[c];
                    }
                }
                totalBeauty += (mx - mn);
            }
        }
        return totalBeauty;
    }
}

